/** Record-type name in the current language (state record names are returned unchanged). */
export const recType = (name) => { const v = REC_TYPES[name]; const i = ["hi", "mr", "gu"].indexOf(lang); return v && i >= 0 ? v[i] : name; };

// The product is BhuSamhita everywhere; earlier strings still say "Land Stack" in running text.
const RENAME = [[/[Tt]he Land Stack/g, "BhuSamhita"], [/Land Stack/g, "BhuSamhita"], [/लैंड स्टैक/g, "BhuSamhita"], [/लँड स्टॅक/g, "BhuSamhita"], [/લેન્ડ સ્ટેક/g, "BhuSamhita"]];
for (const l of Object.keys(STR)) for (const k of Object.keys(STR[l])) {
  if (typeof STR[l][k] === "string") STR[l][k] = RENAME.reduce((v, [re, to]) => v.replace(re, to), STR[l][k]);
}

export const LANGS = [["en", "English"], ["hi", "हिन्दी"], ["mr", "मराठी"], ["gu", "ગુજરાતી"]];

let lang = "en";
try { lang = localStorage.getItem("ls-lang") || "en"; } catch {}
if (!STR[lang]) lang = "en";

export const getLang = () => lang;
export function setLang(l) {
  lang = STR[l] ? l : "en";
  try { localStorage.setItem("ls-lang", lang); } catch {}
  document.documentElement.lang = lang;
  document.dispatchEvent(new Event("langchange"));
}
export const t = (k) => STR[lang][k] ?? STR.en[k] ?? k;

// Show the native-script value when the UI language shares the record's script.
const SCRIPT = { MH: ["mr", "hi"], UP: ["hi", "mr"], GJ: ["gu"] };
export function localText(v, state) {
  if (!v) return "—";
  const native = v.native && (SCRIPT[state] || []).includes(lang);
  return native ? v.native : (v.en || v.native || "—");
}
